        secondaryHandlingPenalty: Number(secondaryHandlingPenalty.toFixed(2)),
        averageLaneClearance: Number((individualLaneClearance.reduce((sum, value) => sum + value, 0) / individualLaneClearance.length).toFixed(2)),
        minimumRouteRetention: Number(Math.min(...individualRouteRetention).toFixed(3)),
