const V35_EVENT_DEFENSIVE_TARGET_TYPES = new Set([
  "defense-point-of-attack",
  "defense-screen",
  "defense-screen-big",
  "defense-chase",
  "defense-switch",
  "defense-post",
  "defense-transition",
  "defense-rebound-coverage"
]);

const V35_EVENT_STABLE_ACTION_TYPES = new Set([
  "deep-range",
  "perimeter-shooting",
  "playmaking",
  "rim-finishing",
  "post-offense",
  "defense-perimeter",
  "defense-help",
  "defense-rim",
  "rebounding-offense",
  "rebounding-defense"
]);

function v35EventNumber(...values) {
  for (const value of values) {
    if (value != null && Number.isFinite(Number(value))) return Number(value);
  }
  return null;
}

function v35EventClamp(value, low = 0, high = 100) {
  return Math.max(low, Math.min(high, Number(value) || 0));
}

function v35EventCardPositions(card) {
  const fromSlots = Array.isArray(card?.slots)
    ? card.slots.map(slot => ({ 1: "PG", 2: "SG", 3: "SF", 4: "PF", 5: "C" })[slot] || String(slot))
    : [];
  const fromText = String(card?.pos || card?.primaryPosition || "")
    .split(/[\/,|-]/)
    .map(value => value.trim().toUpperCase())
    .filter(Boolean);
  return [...new Set([...fromSlots, ...fromText])];
}

function v35EventCardProfile(card, roleProfile = null) {
  const v35 = card?.v35 || {};
  const runtime = v35.runtime || card?.runtime || {};
  const canonical = v35.canonical || card?.canonical || {};
  const observed = v35.observed || card?.observed || {};
  const defense = v35.defense?.runtime || card?.defense?.runtime || {};
  const physics = v35.physics?.runtime || card?.physics?.runtime || {};
  const physicsComponents = v35.physics?.components || card?.physics?.components || {};
  const positions = v35EventCardPositions(card);
  const isGuard = positions.some(position => ["PG", "SG"].includes(position));
  const isWing = positions.some(position => ["SG", "SF"].includes(position));
  const isBig = positions.some(position => ["PF", "C"].includes(position));
  const manual = card?.manual || {};
  const isV35 = Boolean(card?.v35);

  const perimeterShootingVolume = v35EventNumber(
    canonical.perimeterShootingVolume,
    roleProfile?.threePointVolume,
    runtime.perimeterShootingVolume,
    manual.shoot,
    card?.shoot
  );
  const threePointFrequency = v35EventNumber(
    runtime.threePointFrequency,
    canonical.threePointFrequency,
    observed.threePointFrequency,
    card?.seasonStats?.threeAttempts != null && card?.seasonStats?.fga
      ? Number(card.seasonStats.threeAttempts) / Number(card.seasonStats.fga)
      : null
  );

  return {
    positions,
    isGuard,
    isWing,
    isBig,
    impact: isV35
      ? v35EventNumber(
        canonical.personalOffenseValue != null && defense.defensiveImpact != null
          ? Number(canonical.personalOffenseValue) * .62 + Number(defense.defensiveImpact) * .38
          : null,
        runtime.scoringImpact,
        defense.defensiveImpact,
        60
      )
      : v35EventNumber(card?.impact, manual.impact, card?.ovr, manual.ovr, 60),
    offense: isV35
      ? v35EventNumber(canonical.personalOffenseValue, runtime.scoringImpact, 60)
      : v35EventNumber(card?.off, manual.off, card?.ovr, manual.ovr, 60),
    defense: isV35
      ? v35EventNumber(defense.defensiveImpact, 60)
      : v35EventNumber(card?.def, manual.def, 60),
    pass: isV35
      ? v35EventNumber(runtime.purePlaymaking, canonical.playmakingCreation, 60)
      : v35EventNumber(card?.pass, manual.pass, 60),
    usage: isV35
      ? v35EventNumber(runtime.possessionDemand, canonical.possessionDemand, 60)
      : v35EventNumber(card?.usage, manual.usage, runtime.usage, 60),
    rebound: isV35
      ? v35EventNumber(
        runtime.offensiveRebounding != null && runtime.defensiveRebounding != null
          ? Number(runtime.offensiveRebounding) * .38 + Number(runtime.defensiveRebounding) * .62
          : null,
        runtime.rebCompatibility,
        60
      )
      : v35EventNumber(card?.reb, manual.reb, runtime.rebCompatibility, 60),

    perimeterGravity: v35EventNumber(
      runtime.perimeterGravity,
      roleProfile?.observedShootingGravity,
      card?.space,
      manual.space,
      60
    ),
    modernPerimeterGravity: v35EventNumber(
      runtime.modernPerimeterGravity,
      roleProfile?.modernShootingGravity,
      roleProfile?.shootingGravity,
      runtime.perimeterGravity,
      card?.space,
      manual.space,
      60
    ),
    portableJumper: v35EventNumber(
      runtime.portableJumper,
      roleProfile?.portableJumper,
      runtime.jumpShooting,
      card?.shoot,
      manual.shoot,
      60
    ),
    jumpShooting: v35EventNumber(
      runtime.jumpShooting,
      roleProfile?.jumpShooting,
      card?.shoot,
      manual.shoot,
      60
    ),
    perimeterShootingVolume,
    perimeterShootingEfficiency: v35EventNumber(
      canonical.perimeterShootingEfficiency,
      observed.threePct != null ? Number(observed.threePct) * 100 : null,
      card?.seasonStats?.three != null ? Number(card.seasonStats.three) * 100 : null
    ),
    threePointFrequency,
    midRangeFrequency: v35EventNumber(runtime.midRangeFrequency, canonical.midRangeFrequency),
    midRangeEfficiency: v35EventNumber(canonical.midRangeEfficiency),
    interiorFinishing: v35EventNumber(
      runtime.interiorFinishing,
      roleProfile?.interiorFinishing,
      card?.finish,
      manual.finish,
      60
    ),
    interiorGravity: v35EventNumber(
      runtime.interiorGravity,
      roleProfile?.interiorGravity,
      60
    ),
    postScoringUtility: v35EventNumber(
      runtime.postScoringUtility,
      roleProfile?.postScoringUtility
    ),
    selfCreationAbility: v35EventNumber(
      runtime.selfCreationAbility,
      roleProfile?.selfCreationAbility,
      card?.off,
      manual.off,
      60
    ),
    scoringImpact: v35EventNumber(
      runtime.scoringImpact,
      roleProfile?.scoringImpact,
      card?.off,
      manual.off,
      60
    ),
    purePlaymaking: v35EventNumber(
      runtime.purePlaymaking,
      roleProfile?.purePlaymaking,
      roleProfile?.secondaryPlaymaking,
      card?.pass,
      manual.pass,
      60
    ),
    secondaryPlaymaking: v35EventNumber(
      roleProfile?.secondaryPlaymaking,
      runtime.purePlaymaking,
      card?.pass,
      manual.pass,
      60
    ),
    possessionDemand: v35EventNumber(
      runtime.possessionDemand,
      roleProfile?.possessionDemand,
      card?.usage,
      manual.usage,
      60
    ),
    offBallScalability: v35EventNumber(
      runtime.offBallScalability,
      roleProfile?.offBallScalability
    ),
    perimeterOffBallValue: v35EventNumber(
      runtime.perimeterOffBallValue,
      roleProfile?.perimeterOffBallValue
    ),
    interiorOffBallValue: v35EventNumber(
      runtime.interiorOffBallValue,
      roleProfile?.interiorOffBallValue
    ),
    turnoverSecurity: v35EventNumber(roleProfile?.turnoverSecurity),
    freeThrowPct: v35EventNumber(
      observed.ftPct,
      card?.seasonStats?.ft,
      card?.stats?.ftPct
    ),

    perimeterDefense: v35EventNumber(
      defense.pointOfAttackDefense,
      roleProfile?.perimeterDefense,
      card?.def,
      manual.def,
      60
    ),
    switchDefense: v35EventNumber(
      defense.switchDefense,
      roleProfile?.switchDefense,
      card?.def,
      manual.def,
      60
    ),
    helpDefense: v35EventNumber(
      defense.helpDefense,
      roleProfile?.helpDefense,
      card?.def,
      manual.def,
      60
    ),
    interiorDefense: v35EventNumber(
      defense.interiorDefense,
      roleProfile?.interiorDefense,
      card?.def,
      manual.def,
      60
    ),
    rimProtection: v35EventNumber(
      defense.rimProtection,
      roleProfile?.rimProtection,
      card?.def,
      manual.def,
      60
    ),
    defensiveImpact: v35EventNumber(
      defense.defensiveImpact,
      roleProfile?.defensiveImpact,
      card?.def,
      manual.def,
      60
    ),
    defensiveStatChasingRisk: v35EventNumber(
      defense.defensiveStatChasingRisk,
      roleProfile?.defensiveStatChasingRisk,
      0
    ),
    reboundCollectionRisk: v35EventNumber(defense.reboundCollectionRisk, 0),
    offensiveRebounding: v35EventNumber(
      runtime.offensiveRebounding,
      roleProfile?.offensiveRebounding,
      card?.reb,
      manual.reb,
      60
    ),
    defensiveRebounding: v35EventNumber(
      runtime.defensiveRebounding,
      roleProfile?.defensiveRebounding,
      card?.reb,
      manual.reb,
      60
    ),
    sizePresence: v35EventNumber(physics.sizePresence, physicsComponents.size, 60),
    contactCapacity: v35EventNumber(
      physics.contactCapacity,
      physicsComponents.strength,
      60
    ),
    mobilityBaseline: v35EventNumber(
      physics.mobilityBaseline,
      physicsComponents.lateralMovement,
      physicsComponents.agility,
      60
    )
  };
}

function v35EventStableDeepRangeEvidence(card, roleProfile = null) {
  const profile = v35EventCardProfile(card, roleProfile);
  const frequency = profile.threePointFrequency;
  const stable = profile.perimeterShootingVolume >= 84
    && frequency != null
    && frequency >= 0.36
    && profile.portableJumper >= 80
    && profile.modernPerimeterGravity >= 82
    && (
      profile.perimeterShootingEfficiency == null
      || profile.perimeterShootingEfficiency >= 40
      || profile.jumpShooting >= 82
    );
  const anomalyOnly = !stable
    && frequency != null
    && frequency > 0
    && (
      frequency >= 0.04
      || profile.perimeterShootingVolume >= 25
    );
  return {
    stable,
    anomalyOnly,
    probabilityTier: stable ? "rare-stable-capability" : anomalyOnly ? "exception-only" : "ineligible",
    profile: {
      perimeterShootingVolume: profile.perimeterShootingVolume,
      perimeterShootingEfficiency: profile.perimeterShootingEfficiency,
      threePointFrequency: profile.threePointFrequency,
      portableJumper: profile.portableJumper,
      modernPerimeterGravity: profile.modernPerimeterGravity
    }
  };
}

function v35EventOpponentStyle(card, roleProfile = null) {
  if (!card) return { style: "genericCreator", reason: "opponent-card-unavailable" };
  const p = v35EventCardProfile(card, roleProfile);
  if (v35EventStableDeepRangeEvidence(card, roleProfile).stable) {
    return { style: "deepShooter", reason: "stable-deep-range-evidence" };
  }
  if (p.isBig && p.purePlaymaking >= 82 && p.scoringImpact >= 75) {
    return { style: "interiorHub", reason: "big-organization-hub-evidence" };
  }
  if (p.isBig && p.postScoringUtility != null && p.postScoringUtility >= 80) {
    return { style: "postScorer", reason: "post-route-evidence" };
  }
  if (p.perimeterShootingVolume >= 72
    && p.portableJumper >= 80
    && (p.perimeterOffBallValue || 0) >= 78) {
    return { style: "movementShooter", reason: "movement-shooting-evidence" };
  }
  if (p.purePlaymaking >= 80 && p.selfCreationAbility >= 76) {
    return { style: "pickAndRollCreator", reason: "creation-and-organization-evidence" };
  }
  if (p.isWing && p.defensiveImpact >= 84 && p.scoringImpact >= 76) {
    return { style: "twoWayWing", reason: "two-way-wing-evidence" };
  }
  if (p.interiorGravity >= 82 && p.selfCreationAbility >= 76) {
    return { style: "rimCreator", reason: "rim-pressure-creation-evidence" };
  }
  if (p.midRangeFrequency != null
    && p.midRangeFrequency >= .28
    && p.midRangeEfficiency != null
    && p.midRangeEfficiency >= 50
    && p.selfCreationAbility >= 74) {
    return { style: "midrangeCreator", reason: "midrange-volume-and-creation-evidence" };
  }
  if (p.isBig && p.offensiveRebounding >= 82 && p.interiorFinishing >= 78) {
    return { style: "interiorPower", reason: "interior-power-evidence" };
  }
  return { style: "genericCreator", reason: "no-specific-opponent-style-proven" };
}

function v35EventGeneralActorWeight(card, roleProfile = null) {
  const p = v35EventCardProfile(card, roleProfile);
  return p.scoringImpact * .30
    + p.selfCreationAbility * .18
    + p.purePlaymaking * .18
    + p.defensiveImpact * .22
    + (p.offBallScalability || 60) * .12;
}

function v35EventDecisionRiskWeight(card, roleProfile = null) {
  const p = v35EventCardProfile(card, roleProfile);
  return Number(card?.risk?.decisionMaking || 0) * 3
    + Math.max(0, 82 - p.purePlaymaking) * .03
    + p.possessionDemand * .008;
}

function v35EventDeficit(value, threshold) {
  return Math.max(0, threshold - (Number(value) || 0));
}

function v35EventTargetRisk(card, type, roleProfile = null) {
  const p = v35EventCardProfile(card, roleProfile);
  const statRisk = v35EventClamp(p.defensiveStatChasingRisk, 0, 1) * 8;
  const collectionRisk = v35EventClamp(p.reboundCollectionRisk, 0, 1) * 8;
  let score = 0;
  let compatible = true;
  let protectedFromGeneric = false;

  if (type === "defense-point-of-attack") {
    score = v35EventDeficit(p.perimeterDefense, 84) * 0.68
      + v35EventDeficit(p.switchDefense, 80) * 0.22
      + v35EventDeficit(p.mobilityBaseline, 74) * 0.10
      + statRisk;
    protectedFromGeneric = p.perimeterDefense >= 86 && p.switchDefense >= 82;
  } else if (type === "defense-screen" || type === "defense-screen-big") {
    compatible = type !== "defense-screen-big" || p.isBig;
    score = v35EventDeficit(p.perimeterDefense, 82) * 0.42
      + v35EventDeficit(p.switchDefense, 83) * 0.48
      + v35EventDeficit(p.mobilityBaseline, 72) * 0.10
      + statRisk * 0.5;
    protectedFromGeneric = p.perimeterDefense >= 86 && p.switchDefense >= 84;
  } else if (type === "defense-chase") {
    compatible = p.isGuard || p.isWing;
    score = v35EventDeficit(p.perimeterDefense, 84) * 0.72
      + v35EventDeficit(p.mobilityBaseline, 76) * 0.18
      + v35EventDeficit(p.switchDefense, 78) * 0.10
      + statRisk * 0.5;
    protectedFromGeneric = p.perimeterDefense >= 87 && p.mobilityBaseline >= 76;
  } else if (type === "defense-switch") {
    score = v35EventDeficit(p.switchDefense, 84) * 0.72
      + v35EventDeficit(p.perimeterDefense, 78) * 0.12
      + v35EventDeficit(p.interiorDefense, 72) * 0.16
      + statRisk * 0.5;
    protectedFromGeneric = p.switchDefense >= 86;
  } else if (type === "defense-post") {
    const positionMismatch = p.isGuard && !p.isBig ? 6 : p.isWing && !p.isBig ? 2 : 0;
    score = v35EventDeficit(p.interiorDefense, 80) * 0.48
      + v35EventDeficit(p.contactCapacity, 64) * 0.24
      + v35EventDeficit(p.sizePresence, 60) * 0.18
      + v35EventDeficit(p.switchDefense, 76) * 0.10
      + positionMismatch;
    protectedFromGeneric = p.interiorDefense >= 84
      && p.contactCapacity >= 64
      && p.sizePresence >= 60;
  } else if (type === "defense-transition") {
    score = v35EventDeficit(p.perimeterDefense, 78) * 0.34
      + v35EventDeficit(p.helpDefense, 78) * 0.36
      + v35EventDeficit(p.mobilityBaseline, 72) * 0.30
      + statRisk * 0.5;
    protectedFromGeneric = p.helpDefense >= 84 && p.perimeterDefense >= 82;
  } else if (type === "defense-rebound-coverage") {
    score = v35EventDeficit(p.defensiveRebounding, 82) * 0.62
      + v35EventDeficit(p.helpDefense, 78) * 0.25
      + v35EventDeficit(p.sizePresence, 56) * 0.13
      + collectionRisk;
    protectedFromGeneric = p.defensiveRebounding >= 84 && p.helpDefense >= 79;
  }

  return {
    type,
    score: Number(score.toFixed(3)),
    compatible,
    protectedFromGeneric,
    profile: p
  };
}

function v35EventTargetThreshold(type) {
  if (type === "defense-post") return 5;
  if (type === "defense-rebound-coverage") return 4.5;
  if (type === "defense-screen-big") return 4;
  return 3.5;
}

function v35EventGenericTargetability(card, roleProfile = null) {
  const types = [
    "defense-point-of-attack",
    "defense-screen",
    "defense-switch",
    "defense-post"
  ];
  const risks = types.map(type => v35EventTargetRisk(card, type, roleProfile));
  const strongest = [...risks].sort((left, right) => right.score - left.score)[0];
  return Boolean(
    strongest
    && strongest.compatible
    && strongest.score >= Math.max(5, v35EventTargetThreshold(strongest.type))
    && !strongest.protectedFromGeneric
  );
}

function v35EventTemplateText(event) {
  return [
    ...(event?.titleTemplates || []),
    ...(event?.detailTemplates || [])
  ].join(" ");
}

function v35EventSemanticTypes(event, slot = "player") {
  const explicit = V35_EVENT_SEMANTIC_OVERRIDES[event?.id]?.[slot];
  const types = explicit ? [...explicit] : [];
  const text = v35EventTemplateText(event);

  if (slot === "player" && (event?.requiredTraits || []).includes("deepRange")) {
    types.push("deep-range");
  }
  if (!explicit && slot === "player") {
    if (event?.family === "shooting-gravity") types.push("perimeter-shooting");
    if (event?.family === "creator-rhythm") types.push("playmaking");
    if (event?.family === "paint-and-glass") {
      if (/篮板|卡位|冲抢/.test(text)) {
        types.push(/前场篮板|二次进攻|冲抢/.test(text) ? "rebounding-offense" : "rebounding-defense");
      } else if (/护框|封堵|守住禁区/.test(text)) {
        types.push("defense-rim");
      } else {
        types.push("rim-finishing");
      }
    }
    if (event?.family === "defensive-identity") {
      if (/护框|封堵|篮下结束|禁区/.test(text)) types.push("defense-rim");
      else if (/篮板|卡位/.test(text)) types.push("rebounding-defense");
      else if (/协防|补位|轮转/.test(text)) types.push("defense-help");
      else types.push("defense-perimeter");
    }
    if (event?.family === "paint-and-rebounding-playoffs") {
      if (/护框|封堵|禁区/.test(text)) types.push("defense-rim");
      if (/篮板|卡位|冲抢/.test(text)) {
        types.push(/前场篮板|二次进攻|冲抢/.test(text) ? "rebounding-offense" : "rebounding-defense");
      }
      if (/顺下|终结|篮下得分/.test(text)) types.push("rim-finishing");
    }
    if (event?.family === "creator-counter") types.push("offense-primary-creator");
  }

  return [...new Set(types)];
}

function v35EventRequiredTraitsSatisfied(event, traits, card, roleData = null) {
  const required = event?.requiredTraits || [];
  if (!required.length) return true;
  const semanticTypes = new Set(v35EventSemanticTypes(event, "player"));
  return required.every(trait => {
    if (traits?.has?.(trait)) return true;
    if (trait === "deepRange") {
      return v35EventStableDeepRangeEvidence(card, roleData?.profile || roleData || null).stable;
    }
    if (trait === "targetable") {
      return v35EventGenericTargetability(card, roleData?.profile || roleData || null);
    }
    if (trait === "perimeterDefense" && [
      "defense-rim",
      "defense-help",
      "rebounding-defense"
    ].some(type => semanticTypes.has(type))) {
      return true;
    }
    if (trait === "interiorFinishing" && [
      "defense-rim",
      "rebounding-offense",
      "rebounding-defense",
      "offense-post"
    ].some(type => semanticTypes.has(type))) {
      return true;
    }
    return false;
  });
}

function v35EventLineupRequirement(event, list, currentCard = null) {
  if (event?.id !== "po-opponent-09") {
    return { eligible: true, reason: "no-extra-lineup-requirement" };
  }
  const hasNonShooter = (list || []).some(card => {
    if (currentCard && card?.id === currentCard?.id) return false;
    const p = v35EventCardProfile(card);
    return p.modernPerimeterGravity <= 72
      && (p.threePointFrequency == null || p.threePointFrequency <= 0.22)
      && p.perimeterShootingVolume <= 55;
  });
  return {
    eligible: hasNonShooter,
    reason: hasNonShooter
      ? "lineup-has-evidenced-nonshooter"
      : "story-refers-to-unbound-nonshooter-but-lineup-has-none"
  };
}

function v35EventCapabilityEvaluation(type, card, roleProfile = null) {
  const p = v35EventCardProfile(card, roleProfile);
  let eligible = true;
  let score = 50;
  let reason = "semantic-rule-passed";
  let probabilityTier = V35_EVENT_STABLE_ACTION_TYPES.has(type) ? "standard" : "contextual";

  if (type === "deep-range") {
    const evidence = v35EventStableDeepRangeEvidence(card, roleProfile);
    eligible = evidence.stable;
    score = evidence.stable
      ? Math.min(100, p.perimeterShootingVolume * 0.45
        + p.portableJumper * 0.25
        + p.modernPerimeterGravity * 0.20
        + (p.threePointFrequency || 0) * 100 * 0.10)
      : 0;
    probabilityTier = evidence.probabilityTier;
    reason = evidence.stable
      ? "stable-deep-range-evidence"
      : evidence.anomalyOnly
        ? "exception-only-shot-cannot-use-stable-tactical-template"
        : "no-deep-range-evidence";
  } else if (type === "perimeter-shooting") {
    eligible = p.perimeterShootingVolume >= 60
      && p.portableJumper >= 75
      && p.modernPerimeterGravity >= 77;
    score = (p.perimeterShootingVolume + p.portableJumper + p.modernPerimeterGravity) / 3;
    reason = eligible ? "perimeter-shot-role-supported" : "perimeter-shot-role-unsupported";
  } else if (type === "playmaking") {
    eligible = p.purePlaymaking >= 78 || p.pass >= 84;
    score = Math.max(p.purePlaymaking, p.pass);
    reason = eligible ? "playmaking-supported" : "playmaking-below-story-threshold";
  } else if (type === "rim-finishing") {
    eligible = p.interiorFinishing >= 82 || p.interiorGravity >= 84;
    score = Math.max(p.interiorFinishing, p.interiorGravity);
    reason = eligible ? "rim-action-supported" : "rim-action-unsupported";
  } else if (type === "post-offense" || type === "offense-post") {
    eligible = (p.postScoringUtility != null && p.postScoringUtility >= 75)
      || p.interiorGravity >= 84;
    score = Math.max(p.postScoringUtility || 0, p.interiorGravity || 0);
    reason = eligible ? "post-action-supported" : "post-action-unsupported";
  } else if (type === "defense-perimeter") {
    eligible = p.perimeterDefense >= 82 || p.switchDefense >= 85;
    score = Math.max(p.perimeterDefense, p.switchDefense);
    reason = eligible ? "perimeter-defense-supported" : "perimeter-defense-unsupported";
  } else if (type === "defense-help") {
    eligible = p.helpDefense >= 78;
    score = p.helpDefense;
    reason = eligible ? "help-defense-role-supported" : "help-defense-role-unsupported";
  } else if (type === "defense-rim") {
    eligible = p.rimProtection >= 80 || (p.isBig && p.interiorDefense >= 84);
    score = Math.max(p.rimProtection, p.interiorDefense);
    reason = eligible ? "rim-defense-supported" : "rim-defense-unsupported";
  } else if (type === "defense-interior-role") {
    eligible = p.isBig || p.interiorDefense >= 78;
    score = Math.max(p.interiorDefense, p.rimProtection);
    reason = eligible ? "interior-role-supported" : "interior-role-unsupported";
  } else if (type === "rebounding-offense") {
    eligible = p.offensiveRebounding >= 78;
    score = p.offensiveRebounding;
    reason = eligible ? "offensive-rebound-role-supported" : "offensive-rebound-role-unsupported";
  } else if (type === "rebounding-defense") {
    eligible = p.defensiveRebounding >= 78;
    score = p.defensiveRebounding;
    reason = eligible ? "defensive-rebound-role-supported" : "defensive-rebound-role-unsupported";
  } else if (type === "offense-primary-creator") {
    eligible = p.selfCreationAbility >= 78
      || p.scoringImpact >= 82
      || p.purePlaymaking >= 84;
    score = Math.max(p.selfCreationAbility, p.scoringImpact, p.purePlaymaking);
    reason = eligible ? "primary-creator-supported" : "primary-creator-unsupported";
  } else if (type === "offense-secondary-handler") {
    eligible = p.secondaryPlaymaking >= 74 || p.pass >= 78;
    score = Math.max(p.secondaryPlaymaking, p.pass);
    reason = eligible ? "secondary-handler-supported" : "secondary-handler-unsupported";
  } else if (type === "offense-spacing-support") {
    eligible = p.modernPerimeterGravity >= 76
      || (p.offBallScalability != null && p.offBallScalability >= 72)
      || (p.perimeterOffBallValue != null && p.perimeterOffBallValue >= 72);
    score = Math.max(
      p.modernPerimeterGravity,
      p.offBallScalability || 0,
      p.perimeterOffBallValue || 0
    );
    reason = eligible ? "spacing-support-supported" : "spacing-support-unsupported";
  } else if (type === "offense-movement") {
    eligible = p.perimeterShootingVolume >= 62
      && p.portableJumper >= 75
      && (
        p.perimeterOffBallValue == null
        || p.perimeterOffBallValue >= 55
      );
    score = Math.max(p.perimeterShootingVolume, p.perimeterOffBallValue || 0);
    reason = eligible ? "movement-offense-supported" : "movement-offense-unsupported";
  } else if (type === "offense-nonshooter") {
    eligible = p.modernPerimeterGravity <= 72
      && (p.threePointFrequency == null || p.threePointFrequency <= 0.22)
      && p.perimeterShootingVolume <= 55;
    score = Math.max(0, 100 - (
      p.modernPerimeterGravity * 0.45
      + p.perimeterShootingVolume * 0.35
      + p.portableJumper * 0.20
    ));
    reason = eligible ? "evidenced-nonshooter" : "not-a-nonshooter";
  } else if (type === "offense-zone-counter") {
    const hasCreatorRoute = p.selfCreationAbility >= 76 || p.interiorGravity >= 82;
    const exposedCounter = p.modernPerimeterGravity < 80 || p.purePlaymaking < 78;
    eligible = hasCreatorRoute && exposedCounter;
    score = Math.max(0, 88 - Math.max(p.modernPerimeterGravity, p.purePlaymaking));
    reason = eligible ? "zone-can-remove-first-route" : "zone-counter-story-not-supported";
  } else if (type === "offense-pullup-unfamiliar") {
    const directMidrangeEvidence = p.midRangeEfficiency != null && p.midRangeFrequency != null;
    eligible = p.selfCreationAbility >= 74
      && directMidrangeEvidence
      && p.midRangeFrequency <= .22
      && p.midRangeEfficiency < 66;
    score = directMidrangeEvidence
      ? Math.max(0, 80 - p.midRangeEfficiency) * Math.max(0, .28 - p.midRangeFrequency)
      : 0;
    reason = eligible
      ? "low-volume-weak-midrange-is-unfamiliar"
      : directMidrangeEvidence
        ? "familiar-midrange-cannot-use-unfamiliar-wording"
        : "no-midrange-evidence-no-negative-claim";
  } else if (type === "offense-pullup-counter") {
    const directMidrangeEvidence = p.midRangeEfficiency != null;
    eligible = p.selfCreationAbility >= 74
      && directMidrangeEvidence
      && p.midRangeEfficiency < 66;
    score = directMidrangeEvidence ? Math.max(0, 80 - p.midRangeEfficiency) : 0;
    reason = eligible
      ? "opponent-can-concede-weak-midrange"
      : directMidrangeEvidence
        ? "midrange-not-a-supported-weakness"
        : "no-midrange-evidence-no-negative-claim";
  } else if (type === "offense-isolation-decision") {
    eligible = p.possessionDemand >= 80
      && (
        p.purePlaymaking < 82
        || (p.turnoverSecurity != null && p.turnoverSecurity < 80)
      );
    score = Math.max(0, p.possessionDemand - Math.max(p.purePlaymaking, p.turnoverSecurity || 0));
    reason = eligible ? "isolation-decision-risk-supported" : "isolation-decision-risk-unsupported";
  } else if (type === "free-throw-liability") {
    eligible = p.freeThrowPct != null && p.freeThrowPct <= 0.72;
    score = p.freeThrowPct == null ? 0 : Math.max(0, (0.78 - p.freeThrowPct) * 200);
    reason = eligible
      ? "low-free-throw-evidence"
      : p.freeThrowPct == null
        ? "no-free-throw-evidence-no-negative-claim"
        : "free-throw-liability-unsupported";
  } else if (type === "transition-communication") {
    // This is an event-state assertion, not a permanent player ability claim.
    eligible = true;
    score = 50;
    reason = "state-dependent-not-baseline-liability";
  }

  return {
    type,
    eligible,
    score: Number((score || 0).toFixed(3)),
    reason,
    probabilityTier,
    profile: p
  };
}

function v35EventSemanticEvaluate(
  event,
  card,
  slot = "player",
  list = [],
  counterpart = null,
  roleProfile = null
) {
  const types = v35EventSemanticTypes(event, slot);
  const lineupRequirement = v35EventLineupRequirement(event, list, card);
  const evaluations = [];

  for (const type of types) {
    if (V35_EVENT_DEFENSIVE_TARGET_TYPES.has(type)) {
      const target = v35EventTargetRisk(card, type, roleProfile);
      const peerRisks = (list || [])
        .filter(item => !counterpart || item?.id !== counterpart?.id)
        .map(item => v35EventTargetRisk(item, type))
        .filter(item => item.compatible);
      const maximum = peerRisks.length
        ? Math.max(...peerRisks.map(item => item.score))
        : target.score;
      const threshold = v35EventTargetThreshold(type);
      const nearActualWeakness = target.score >= maximum - 1.5;
      const eligible = target.compatible
        && target.score >= threshold
        && !target.protectedFromGeneric
        && nearActualWeakness;
      evaluations.push({
        type,
        eligible,
        score: target.score,
        maximumLineupRisk: Number(maximum.toFixed(3)),
        threshold,
        probabilityTier: target.score >= threshold + 8 ? "notable" : "conditional",
        reason: !target.compatible
          ? "role-position-incompatible"
          : target.protectedFromGeneric
            ? "elite-axis-protection"
            : target.score < threshold
              ? "no-meaningful-targeting-risk"
              : !nearActualWeakness
                ? "not-the-lineup-target"
                : "target-risk-supported",
        profile: target.profile
      });
    } else {
      evaluations.push(v35EventCapabilityEvaluation(type, card, roleProfile));
    }
  }

  const eligible = lineupRequirement.eligible
    && evaluations.every(evaluation => evaluation.eligible);
  const scores = evaluations.map(evaluation => evaluation.score);
  return {
    eligible,
    slot,
    types,
    evaluations,
    lineupRequirement,
    score: scores.length ? Math.max(...scores) : 50,
    probabilityTier: evaluations.some(item => item.probabilityTier === "exception-only")
      ? "exception-only"
      : evaluations.some(item => item.probabilityTier === "rare-stable-capability")
        ? "rare-stable-capability"
        : evaluations.some(item => item.probabilityTier === "notable")
          ? "notable"
          : "standard",
    reasons: [
      ...(lineupRequirement.eligible ? [] : [lineupRequirement.reason]),
      ...evaluations.filter(item => !item.eligible).map(item => item.reason)
    ]
  };
}

function v35EventSemanticCandidate(
  event,
  card,
  slot = "player",
  list = [],
  counterpart = null,
  roleData = null
) {
  return v35EventSemanticEvaluate(
    event,
    card,
    slot,
    list,
    counterpart,
    roleData?.profile || roleData || null
  ).eligible;
}

function v35EventSemanticWeight(
  event,
  card,
  slot = "player",
  list = [],
  counterpart = null,
  roleData = null
) {
  const evaluation = v35EventSemanticEvaluate(
    event,
    card,
    slot,
    list,
    counterpart,
    roleData?.profile || roleData || null
  );
  if (!evaluation.eligible) return 0.001;
  if (evaluation.types.some(type => V35_EVENT_DEFENSIVE_TARGET_TYPES.has(type))) {
    return Math.max(0.01, 1 + evaluation.score * evaluation.score);
  }
  if (evaluation.types.includes("offense-nonshooter")
    || evaluation.types.includes("offense-pullup-unfamiliar")
    || evaluation.types.includes("offense-pullup-counter")
    || evaluation.types.includes("offense-isolation-decision")
    || evaluation.types.includes("free-throw-liability")) {
    return Math.max(0.01, 1 + evaluation.score * evaluation.score);
  }
  if (evaluation.types.length) return Math.max(1, evaluation.score);
  const p = v35EventCardProfile(card, roleData?.profile || roleData || null);
  return slot === "support"
    ? p.impact + p.pass + p.defense * 0.25
    : p.impact + p.usage * 0.35 + p.defense * 0.08;
}

function v35EventSelectDefensiveBreakdownTarget(list = []) {
  const ranked = list.map(card => {
    const risks = [
      v35EventTargetRisk(card, "defense-point-of-attack"),
      v35EventTargetRisk(card, "defense-screen"),
      v35EventTargetRisk(card, "defense-switch")
    ].filter(item => item.compatible && !item.protectedFromGeneric);
    const risk = risks.length
      ? [...risks].sort((left, right) => right.score - left.score)[0]
      : null;
    return { card, risk };
  }).filter(entry => entry.risk)
    .sort((left, right) => right.risk.score - left.risk.score);
  const strongest = ranked[0];
  if (!strongest || strongest.risk.score < 4.5) return null;
  return strongest.card;
}

function v35BuildDefensiveBreakdownArc(result, list, actors, context, seed) {
  const target = v35EventSelectDefensiveBreakdownTarget(list);
  const lostRound = context.lostRound;
  if (!target) {
    return {
      id: "defensive-breakdown-team-scheme",
      family: "defensiveBreakdown",
      severity: context.severity,
      tone: "negative",
      badge: "赛季主线",
      headline: "对手不再猜了：每晚都在同一套轮转边界上施压",
      deck: "阵容没有足够明确的个人防守弱点；问题来自整套方案在挡拆覆盖与弱侧轮转之间反复付出同一代价。",
      chapters: [
        narrativeArcChapter("球探报告", "第一支球队把体系取舍写成了公开答案", "对手连续改变掩护角度，再把弱侧射手放到最难协防的位置；联盟复制的是覆盖方案的边界，而不是虚构某位精英防守者为漏洞。", "negative"),
        narrativeArcChapter("录像会议", `${actors.defender.displayName}要求全队统一轮转口令`, `${actors.defender.displayName}尝试提前指挥夹击和换防，但每次变阵都会把压力转移到另一个区域。`, "neutral"),
        lostRound
          ? narrativeArcChapter(lostRound.name, `${lostRound.opponentTeam}把常规赛答案重复到出局`, narrativeArcRoundBeat(lostRound, 0, `${lostRound.opponentTeam}没有强行寻找个人弱点，而是持续攻击同一套覆盖边界。`), "critical")
          : narrativeArcChapter("冲刺阶段", "防守终于稳定，排名已经来不及修复", "球队减少不必要的夹击并统一弱侧轮转，但修正发生在赛季太晚的位置。", "positive"),
        narrativeArcChapter("赛季结局", "问题不是单次失误，而是没有第二套覆盖方案", narrativeArcOutcome(result), "negative")
      ]
    };
  }
  return {
    id: `defensive-breakdown-${target.id}`,
    family: "defensiveBreakdown",
    severity: context.severity,
    tone: "negative",
    badge: "赛季主线",
    headline: `对手不再猜了：每晚都把${target.displayName}拉进同一种进攻`,
    deck: "真正击穿防守的不是一次点名，而是联盟连续复制同一答案后，球队仍没有稳定的保护方案。",
    chapters: [
      narrativeArcChapter("球探报告", "第一支球队把弱点写成了公开答案", `对手连续让${target.displayName}参与高位挡拆，再把弱侧射手放到最难协防的位置；从第二周开始，几乎每支球队都复制这套起手式。`, "negative"),
      narrativeArcChapter("录像会议", `${actors.defender.displayName}要求全队统一轮转口令`, `${actors.defender.displayName}试图提前指挥夹击和换防，${target.displayName}也减少了自由协防，但每次变阵都会把压力转移到另一个角落。`, "neutral"),
      lostRound
        ? narrativeArcChapter(lostRound.name, `${lostRound.opponentTeam}把常规赛答案重复到出局`, narrativeArcRoundBeat(lostRound, 0, `${lostRound.opponentTeam}没有增加复杂战术，只是持续把最弱环节拖进每一次关键挡拆。`), "critical")
        : narrativeArcChapter("冲刺阶段", "防守终于稳定，排名已经来不及修复", `${target.displayName}接受更明确的任务，球队也减少不必要的夹击，但修正发生在赛季太晚的位置。`, "positive"),
      narrativeArcChapter("赛季结局", "问题不是单次失误，而是没有第二套覆盖方案", narrativeArcOutcome(result), "negative")
    ]
  };
}

function v35EventDeclaredRoleTraitData(card, roleProfile = null, options = {}) {
  const profile = v35EventCardProfile(card, roleProfile);
  const roles = new Set(["any"]);
  const traits = new Set();
  const specials = card?.eventProfile?.specials || [];

  // Player labels are summaries of the same underlying evidence. They may be
  // rendered to the user, but must not create event capability a second time.
  if (profile.possessionDemand >= 78
    && (profile.scoringImpact >= 82 || profile.purePlaymaking >= 82)) roles.add("primaryCreator");
  if (profile.positions.some(position => ["SF", "PF"].includes(position))
    && profile.purePlaymaking >= 78) roles.add("pointForward");
  if (profile.isBig && profile.purePlaymaking >= 70
    && Math.max(profile.postScoringUtility || 0, profile.interiorGravity || 0) >= 68) roles.add("postHub");
  if (profile.portableJumper >= 82
    && profile.modernPerimeterGravity >= 82
    && (profile.perimeterOffBallValue || 0) >= 70) roles.add("movementShooter");
  if (profile.portableJumper >= 78 && profile.modernPerimeterGravity >= 78) roles.add("spotUpShooter");
  if (profile.pass >= 76 && profile.offense >= 80) roles.add("secondaryCreator");
  if ((profile.isGuard || profile.isWing) && profile.perimeterDefense >= 87) roles.add("perimeterStopper");
  if (profile.isWing && profile.offense >= 82 && profile.defensiveImpact >= 84) roles.add("twoWayWing");
  if (profile.isBig && profile.rimProtection >= 87) roles.add("rimProtector");
  if (profile.isBig && profile.switchDefense >= 83) roles.add("switchBig");
  if (profile.isBig && profile.interiorFinishing >= 85) roles.add("rollMan");
  if (profile.rebound >= 84 || profile.defensiveRebounding >= 84) roles.add("rebounder");
  if (profile.purePlaymaking >= 70
    && profile.possessionDemand <= 88
    && (profile.offBallScalability || 0) >= 46) roles.add("connector");

  if (profile.pass >= 88 || profile.secondaryPlaymaking >= 89) traits.add("elitePasser");
  if (profile.modernPerimeterGravity >= 88) traits.add("shootingGravity");
  if (options.legacyDeepRange) {
    if (profile.modernPerimeterGravity >= 94 && profile.perimeterShootingVolume >= 90) traits.add("deepRange");
  } else if (v35EventStableDeepRangeEvidence(card, roleProfile).stable) {
    traits.add("deepRange");
  }
  if (profile.modernPerimeterGravity <= 55) traits.add("nonShooter");
  if (profile.perimeterDefense >= 88) traits.add("perimeterDefense");
  if (options.legacyTargetable) {
    if (profile.perimeterDefense <= 72 && profile.switchDefense <= 72) traits.add("targetable");
  } else if (v35EventGenericTargetability(card, roleProfile)) {
    traits.add("targetable");
  }
  if (profile.interiorFinishing >= 88) traits.add("interiorFinishing");
  if (profile.turnoverSecurity != null && profile.turnoverSecurity >= 88) traits.add("lowTurnover");
  if (Number(card?.availability?.durabilityRisk || 0) >= 0.28) traits.add("highDurabilityRisk");
  if (specials.some(item => /Discipline|Suspension|Volatility/.test(item))
    || Number(card?.risk?.defensiveDiscipline || 0) >= 0.45) traits.add("disciplineRisk");
  // Veteran/leadership is a factual event trait, not an ability label. It must
  // therefore come from the explicit event profile rather than display tags.
  if (specials.some(item => /Veteran|Leadership|Mentor/i.test(item))) traits.add("veteran");
  if (profile.rebound >= 86 || profile.defensiveRebounding >= 86) traits.add("rebounding");

  return { roles, traits, profile };
}

    function tier(wins) {
      if (isEnglishLocale()) {
        if (wins >= 70) return "Historic juggernaut";
        if (wins >= 64) return "Super contender";
        if (wins >= 56) return "Title favorite";
        if (wins >= 48) return "Playoff lock";
        if (wins >= 40) return "Play-in contender";
        return "Talented, but structurally risky";
      }
      if (wins >= 70) return "历史级怪物队";
      if (wins >= 64) return "争冠超级强队";
      if (wins >= 56) return "总冠军热门";
      if (wins >= 48) return "稳进季后赛";
      if (wins >= 40) return "附加赛/边缘队";
      return "天赋很高但结构危险";
    }

    function seededPick(items, seedText) {
      return items[Math.min(items.length - 1, Math.floor(seededNoise(seedText) * items.length))];
    }

    function seededWeightedPick(items, weightFor, seedText) {
      if (!items.length) return null;
      const weighted = items.map(item => ({ item, weight: Math.max(.001, Number(weightFor(item)) || 0) }));
      const total = weighted.reduce((sum, entry) => sum + entry.weight, 0);
      let cursor = seededNoise(seedText) * total;
      for (const entry of weighted) {
        cursor -= entry.weight;
        if (cursor <= 0) return entry.item;
      }
      return weighted[weighted.length - 1].item;
    }

