    const playoffOpponentRoundOffsets = {
      "首轮": 0,
      "分区半决赛": 1,
      "分区决赛": 2,
      "附加赛": 3,
      "总决赛": 0
    };

    function playoffPathConference(list, era) {
      const lineupSeed = list.map(card => card.id).join("-");
      return seededNoise(`${lineupSeed}|${era}|playoff-conference`) < .5 ? "east" : "west";
    }

    function playoffOpponentForRound(list, era, roundName, roundIndex = 0, opponentStep = 0) {
      const lineupSeed = list.map(card => card.id).join("-");
      const opponentPool = playoffStoryOpponents[era] || playoffStoryOpponents.balanced;
      const pathConference = playoffPathConference(list, era);
      const opponentConference = roundName === "总决赛"
        ? (pathConference === "east" ? "west" : "east")
        : pathConference;
      const conferencePool = opponentPool.filter(opponent => opponent.conference === opponentConference);
      const eligiblePool = conferencePool.length ? conferencePool : opponentPool;
      const opponentOffset = Math.floor(seededNoise(`${lineupSeed}|${era}|${opponentConference}|opponent-order`) * eligiblePool.length);
      const roundOffset = (playoffOpponentRoundOffsets[roundName] ?? roundIndex) + opponentStep;
      const opponent = eligiblePool[(opponentOffset + roundOffset) % eligiblePool.length];
      return { ...opponent, pathConference };
    }

