    function teamResultSummary(r) {
      if (isEnglishLocale()) {
        const strength = r.wins >= 60 ? "the league's top tier" : r.wins >= 50 ? "the upper tier of its conference" : "the playoff race";
        const finalRound = r.playoff?.rounds?.[r.playoff.rounds.length - 1];
        const wonFinals = r.playoff?.rounds?.some(round => round.name === "总决赛" && round.status === "win");
        const finish = wonFinals
          ? "won the championship"
          : finalRound?.name === "常规赛结束"
            ? "missed the playoffs"
            : finalRound
              ? `finished in the ${localizedRoundName(finalRound.name)}`
              : "is waiting for its playoff result";
        return `${r.wins} wins, placing the team in ${strength}; it ${finish}.`;
      }
      const strength = r.wins >= 60 ? "联盟第一档" : r.wins >= 50 ? "分区前列" : "季后赛竞争区";
      const finalRound = r.playoff?.rounds?.[r.playoff.rounds.length - 1];
      const finish = r.playoff?.rounds?.some(round => round.name === "总决赛" && round.status === "win")
        ? "最终夺冠"
        : finalRound?.name === "常规赛结束"
          ? "没有进入季后赛"
          : finalRound
            ? `止步${finalRound.name}`
            : "等待季后赛结果";
      return `${r.wins} 胜，常规赛处于${strength}；${finish}。`;
    }

