      ctx.fillStyle = backdrop;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      const glow = ctx.createRadialGradient(905, 95, 0, 905, 95, 620);
      glow.addColorStop(0, "rgba(48,174,128,.20)");
