    function setPublicBetaLocale(locale, options = {}) {
      publicBetaLocale = locale === "en" ? "en" : "zh";
      cards.forEach(card => {
        if (!publicBetaChineseLabels.has(card.id)) {
          publicBetaChineseLabels.set(card.id, {
            displayName: card.displayName,
            displayVersion: card.displayVersion
          });
        }
        const chinese = publicBetaChineseLabels.get(card.id);
        card.displayName = publicBetaLocale === "en" ? card.name : chinese.displayName;
        card.displayVersion = publicBetaLocale === "en" ? card.version : chinese.displayVersion;
      });
      if (options.persist !== false) localStorage.setItem("nba82Locale", publicBetaLocale);
      if (options.rerender !== false) render();
      else applyPublicBetaLocale();
      if (lastResult && ratingsRevealed) {
        el.tier.textContent = tier(lastResult.wins);
        el.summary.textContent = teamResultSummary(lastResult);
        el.analysis.innerHTML = buildConcreteReasons(lastResult)
          .map(reason => `<li><b>${reason.title}</b><br>${reason.detail}</li>`)
          .join("");
      }
      if (lastResult && el.seasonModal.classList.contains("is-open")) {
        renderResultModal(lastResult);
      }
    }

