      const allowedPools = new Set(["all", "guard", "frontcourt"]);
      const allowedFilters = new Set(["all", "1", "2", "3", "4", "5"]);
      const settings = {
        era: allowedEras.has(data.settings?.era) ? data.settings.era : "modern",
        pool: allowedPools.has(data.settings?.pool) ? data.settings.pool : "all",
        posFilter: allowedFilters.has(data.settings?.posFilter) ? data.settings.posFilter : "all",
        injury: String(Math.max(0, Math.min(12, Number(data.settings?.injury ?? 5) || 0))),
        chem: String(Math.max(-8, Math.min(8, Number(data.settings?.chem ?? 0) || 0)))
      };
