function observedPrimaryLine(box, primaryId) {
  return box?.players?.find(player => player.cardKey === primaryId) ?? null;
}

function expectedPrimaryLine(team, primaryId, box = null) {
  const roleAdjusted = box?.matchupExpectations?.find(player => player.cardKey === primaryId);
  if (roleAdjusted) return Object.freeze({ ...roleAdjusted });
  const card = team.lineup.find(player => cardKey(player) === primaryId);
  const number = (keys, fallback) => {
    for (const key of keys) {
      const value = Number(card?.seasonStats?.[key] ?? card?.[key]);
      if (Number.isFinite(value)) return value;
    }
    return fallback;
  };
  const pts = number(["ppg", "pts"], 20);
  const fga = number(["fga"], Math.max(8, pts / 1.28));
  const fta = number(["fta"], Math.max(2, pts / 7));
  const fgPct = clamp(number(["fgPct", "fg"], .47), .30, .70);
  return Object.freeze({
    minutes: number(["mpg", "minutes"], 36),
    pts,
    fgm: fga * fgPct,
    fga,
    threePm: number(["threePm", "threePmg"], 1.5),
    threePa: number(["threePa"], 4.5),
    ftm: fta * clamp(number(["ftPct", "ft"], .78), .45, .98),
    fta,
    ast: number(["apg", "ast"], 4),
    tov: number(["tov", "tpg"], 2.4)
  });
}

function evaluateContextEvent({ context, team, box, seed, gameNumber, eventKey }) {
  const primaryId = context?.prepared?.primaryAttackerId;
  const observedLine = observedPrimaryLine(box, primaryId);
  if (!primaryId || !observedLine) return null;
  return evaluatePrimaryMatchupEventV1({
    prepared: context.prepared,
    realization: context.realization,
    expectedLine: expectedPrimaryLine(team, primaryId, box),
    observedLine,
    teamTotals: box?.totals || {},
    seed,
    gameKey: `nba5-game-${gameNumber}|${eventKey}`
  });
}

function evaluateSideEvent({ side, model, team, box, seed, gameNumber }) {
  return evaluateContextEvent({
    context: model[side], team, box, seed, gameNumber, eventKey: `${side}-primary-event`
  });
}

function evaluateFocusEvent({ side, model, team, box, seed, gameNumber }) {
  const focus = model[side]?.focus;
  if (!focus) return null;
  if (focus.sharedWithPrimary) {
    return evaluateSideEvent({ side, model, team, box, seed, gameNumber });
  }
  return evaluateContextEvent({
    context: focus, team, box, seed, gameNumber, eventKey: `${side}-focus-event`
  });
}

function evaluateNBA5PrimaryEvents({ model, teamA, teamB, teamABox, teamBBox, seed, gameNumber }) {
  return Object.freeze({
    teamA: evaluateSideEvent({ side: "teamA", model, team: teamA, box: teamABox, seed, gameNumber }),
    teamB: evaluateSideEvent({ side: "teamB", model, team: teamB, box: teamBBox, seed, gameNumber }),
    teamAFocus: evaluateFocusEvent({ side: "teamA", model, team: teamA, box: teamABox, seed, gameNumber }),
    teamBFocus: evaluateFocusEvent({ side: "teamB", model, team: teamB, box: teamBBox, seed, gameNumber })
  });
}

function secondaryAssignmentRows(model, side) {
  const direction = side === "teamA" ? "aOnOffense" : "bOnOffense";
  return model?.diagnostics?.main?.deterministic?.directions?.[direction]?.assignment?.rows ?? [];
}

function evaluateSecondarySide({ side, model, team, box }) {
  const primaryId = model?.[side]?.prepared?.primaryAttackerId;
  const attackPlan = model?.plans?.[side]?.offense ?? {};
  const defendingSide = side === "teamA" ? "teamB" : "teamA";
  const defensePlan = model?.plans?.[defendingSide]?.defense ?? {};
  const explicitPair = Boolean(attackPlan.primaryAttackerId
    && (defensePlan.leadDefenderId || defensePlan.focusTargetId));
  if (explicitPair) return null;
  const candidates = [];
  for (const row of secondaryAssignmentRows(model, side)) {
    if (!row?.attackerId || row.attackerId === primaryId) continue;
    const observed = observedPrimaryLine(box, row.attackerId);
    if (!observed) continue;
    const expected = expectedPrimaryLine(team, row.attackerId, box);
    const evidence = buildPrimaryMatchupStatEvidenceV1({ expectedLine: expected, observedLine: observed });
    const pointsDelta = Number(evidence.pointsDelta);
    const efficiencyDelta = Number(evidence.trueShootingDelta);
    const volumeDelta = Number(evidence.volumeDelta);
    const offenseClear = pointsDelta >= Math.max(8, expected.pts * .32)
      && efficiencyDelta >= .035 && Number(observed.pts) >= 24;
    const defenseClear = pointsDelta <= -Math.max(8, expected.pts * .34)
      && efficiencyDelta <= -.04 && Number(observed.pts) <= expected.pts * .72;
    if (!offenseClear && !defenseClear) continue;
    candidates.push(Object.freeze({
      event: Object.freeze({
        type: offenseClear ? "secondaryAttackerClearAdvantage" : "secondaryDefenderClearLimit",
        severity: "clear",
        label: offenseClear ? "次要得分点明显占优" : "次要对位限制明显",
        attackerId: row.attackerId,
        defenderId: row.defenderId,
        evidence: Object.freeze({
          pointsDelta: Number(pointsDelta.toFixed(2)),
          trueShootingDelta: Number(efficiencyDelta.toFixed(4)),
          shotVolumeDelta: Number(volumeDelta.toFixed(2))
        }),
        provenance: "secondary-boxscore-plus-one-to-one-assignment"
      }),
      pathEvent: null,
      fallback: true,
      strength: Math.abs(pointsDelta) / Math.max(8, expected.pts * .34) + Math.abs(efficiencyDelta) * 4
    }));
  }
  return candidates.sort((left, right) => right.strength - left.strength
    || left.event.attackerId.localeCompare(right.event.attackerId))[0] ?? null;
}

function evaluateNBA5SecondaryEvents({ model, teamA, teamB, teamABox, teamBBox }) {
  return Object.freeze({
    teamA: evaluateSecondarySide({ side: "teamA", model, team: teamA, box: teamABox }),
    teamB: evaluateSecondarySide({ side: "teamB", model, team: teamB, box: teamBBox })
  });
}

