        event.currentTarget.textContent = h5BattleEnglish() ? "NBA5 copied" : "NBA5 已复制";
        setTimeout(() => { event.currentTarget.textContent = h5BattleEnglish() ? "Copy NBA5" : "复制 NBA5"; }, 1400);
