    globalScope.document.getElementById("onlineRoomConfirmName").addEventListener("click", handleConfirmName);
    globalScope.document.getElementById("onlineRoomName").addEventListener("input", syncNamePreferenceUi);
    globalScope.document.getElementById("onlineRoomJoin").addEventListener("click", () => void handleJoin());
    globalScope.document.getElementById("onlineRoomSubmitLineup").addEventListener("click", () => void handleSubmitLineup());
    globalScope.document.getElementById("onlineRoomStart").addEventListener("click", () => void handleRevealResult());
    globalScope.document.getElementById("onlineRoomOpenPack").addEventListener("click", () => void handleOpenRoomPack());
    globalScope.document.getElementById("onlineRoomKickGuest").addEventListener("click", () => void handleKickGuest());
    globalScope.document.getElementById("onlineRoomRematch").addEventListener("click", () => {
      state.rematchOpen = !state.rematchOpen;
      if (state.room) {
        renderRoom(state.room);
        if (state.rematchOpen) void refreshRoom(state.room.code);
      }
    });
