    for (let x = 0; x <= POSTER_WIDTH; x += 36) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, POSTER_HEIGHT); ctx.stroke(); }
    for (let y = 0; y <= POSTER_HEIGHT; y += 36) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(POSTER_WIDTH, y); ctx.stroke(); }

